#include "stdafx.h"#include "HcdElementBase.h"struct SCAVG_P{#include "PrivateVars/CAVG.h"};class KCAVG : public KHcdElementBase  , protected SCAVG_P{public:  static IHcdElement *Create();protected:  static void InitParm();  virtual void OnCreated( int domain, LPCSTR pszHmiTagName );  virtual void StepCalc( SStepCalcParams &params );};static KHcdFactory _CAVG("CAVG", KCAVG::Create);IHcdElement *KCAVG::Create(){  return new KCAVG;}//////////////////////////////////////////////////////////////////////////#include "_InitInfo.h"DECLARE_PRIVATE_VARSINFO( KCAVG, 9 )void KCAVG::InitParm(){#include "PrivateVars/CAVG.h"  qsort( s_privateVarInfo, s_kprivateVarInfo, sizeof( SVarInfo ), CompVarInfo );}void KCAVG::OnCreated( int domain, LPCSTR pszHmiTagName ){  if( !s_kprivateVarInfo )    InitParm();  m_kPrivateVarsInfo = s_kprivateVarInfo;  m_pPrivateVarsInfo = s_privateVarInfo;  m_pPrivateObject = (BYTE*)this;}void KCAVG::StepCalc( SStepCalcParams &params ){  if( RST )  {    _accum = 0;    _samples = 0;    _time = 0;    return;  }  if( !HOLD )  {    _samples++;    _accum += INU0;  }  _time += params.dtS;  I_AVG = _accum / _samples;  if( _time >= (AvgPeriod*60.f) )  {    P_AVG = I_AVG;    _time = 0;  }}